import { getSupabaseAdmin } from "./supabase";

// The devis interne generated by the expertise IA (before any entreprise is
// involved) needs a real owner in the `quotes` table's user_id column — it
// belongs to Amira until an entreprise picks up the offer, since she's the
// one alerted and able to correct it. Resolves her real Supabase Auth id by
// email via the service-role client (no RLS token exists for this yet).
const PRIMARY_ADMIN_EMAIL = "bouhouchimira@gmail.com";

let cachedAdminUserId = "";

export async function resolveAdminUserId() {
  if (cachedAdminUserId) return cachedAdminUserId;
  const { data, error } = await getSupabaseAdmin()
    .from("users")
    .select("id")
    .eq("email", PRIMARY_ADMIN_EMAIL)
    .maybeSingle();
  if (error || !data?.id) return "";
  cachedAdminUserId = data.id;
  return cachedAdminUserId;
}

export { PRIMARY_ADMIN_EMAIL };
